/**
 * @summary List citations for a document
 */
export const getListCitationsUrl = (params: ListCitationsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/citations?${stringifiedParams}`
    : `/api/citations`;
};

export const listCitations = async (
  params: ListCitationsParams,
  options?: RequestInit,
): Promise<Citation[]> => {
  return customFetch<Citation[]>(getListCitationsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListCitationsQueryKey = (params?: ListCitationsParams) => {
  return [`/api/citations`, ...(params ? [params] : [])] as const;
};

